    'translation',  -- exercise_type (dùng translation cho fill blank)
    JSON_QUOTE('[{"question_id":1,"question":"_____ somebody The baby had been abandoned by its mother.","hint":"to leave somebody, especially somebody you are responsible for, with no intention of returning","correct_answer":"abandon"},{"question_id":2,"question":"This tax should be _____.","hint":"to officially end a law, a system or an institution","correct_answer":"abolish"},{"question_id":3,"question":"I''''ve joined a class for _____ beginners.","hint":"total and complete","correct_answer":"absolute"},{"question_id":4,"question":"_____ something Plants absorb carbon dioxide from the air.","hint":"to take in a liquid, gas or other substance from the surface or space around","correct_answer":"absorb"},{"question_id":5,"question":"_____ knowledge/principles","hint":"based on general ideas and not on any particular real person, thing or situation","correct_answer":"abstract"},{"question_id":6,"question":"That uniform makes the guards look _____.","hint":"extremely silly; not logical and sensible","correct_answer":"absurd"},{"question_id":7,"question":"High-speed internet _____ has become a necessity.","hint":"the opportunity or right to use something or to see somebody/something","correct_answer":"access"},{"question_id":8,"question":"The hotel can _____ up to 500 guests.","hint":"to provide somebody with a room or place to sleep, live or sit","correct_answer":"accommodate"},{"question_id":9,"question":"_____ somebody/something + adv./prep. His wife accompanied him on the trip.","hint":"to travel or go somewhere with somebody/something","correct_answer":"accompany"},{"question_id":10,"question":"They questioned the _____ of the information in the file.","hint":"the state of being exact or correct; the ability to do something with skill and without making mistakes","correct_answer":"accuracy"},{"question_id":11,"question":"_____ somebody of something to accuse somebody of murder/a crime","hint":"to say that somebody has done something wrong or is guilty of something","correct_answer":"accuse"},{"question_id":12,"question":"She has _____ a good knowledge of English.","hint":"to gain something by your own efforts, ability or behaviour","correct_answer":"acquire"},{"question_id":13,"question":"theories of child language _____","hint":"the act of getting something, especially knowledge, a skill, etc.","correct_answer":"acquisition"},{"question_id":14,"question":"The burglar alarm is _____ by movement.","hint":"to make something such as a device or chemical process start working","correct_answer":"activate"},{"question_id":15,"question":"There is an _____ shortage of water.","hint":"very serious or severe","correct_answer":"acute"},{"question_id":16,"question":"It''''s amazing how soon you _____.","hint":"to change your behaviour in order to deal more successfully with a new situation","correct_answer":"adapt"},{"question_id":17,"question":"What''''s your name and _____?","hint":"details of where somebody lives or works and where letters, etc. can be sent","correct_answer":"address"},{"question_id":18,"question":"They''''ll need an _____ supply of hot water.","hint":"enough in quantity, or good enough in quality, for a particular purpose or need","correct_answer":"adequate"},{"question_id":19,"question":"Once in the bloodstream, the bacteria _____ to the surface of the red cells.","hint":"to stick to something","correct_answer":"adhere"},{"question_id":20,"question":"The planes landed on _____ runways.","hint":"next to something","correct_answer":"adjacent"},{"question_id":21,"question":"_____ something Watch out for sharp bends and adjust your speed accordingly.","hint":"to change something slightly to make it more suitable for a new set of conditions or to make it work better","correct_answer":"adjust"},{"question_id":22,"question":"_____ between the ages of 13 and 18 and the problems they face","hint":"a young person who is developing from a child into an adult","correct_answer":"adolescent"},{"question_id":23,"question":"a campaign to encourage childless couples to _____","hint":"to take somebody else’s child into your family and become its legal parent(s)","correct_answer":"adopt"},{"question_id":24,"question":"_____ for something/somebody an advocate for hospital workers","hint":"a person who supports or speaks in favour of somebody or of a public plan or action","correct_answer":"advocate"},{"question_id":25,"question":"the _____ appeal of the songs","hint":"connected with beauty and art and the understanding of beautiful things","correct_answer":"aesthetic"},{"question_id":26,"question":"How will these changes _____ us?","hint":"to produce a change in somebody/something","correct_answer":"affect"},{"question_id":27,"question":"_____ something (for something) A large sum has been allocated for buying new books for the library.","hint":"to give something officially to somebody/something for a particular purpose","correct_answer":"allocate"},{"question_id":28,"question":"Prices have not _____ significantly this year.","hint":"to become different; to make somebody/something different","correct_answer":"alter"},{"question_id":29,"question":"The road was closed so we had to find an _____ route.","hint":"that can be used instead of something else","correct_answer":"alternative"},{"question_id":30,"question":"_____ (between A and B) The teacher drew an analogy between the human heart and a pump.","hint":"a comparison of one thing with another thing that has similar features; a feature that is similar","correct_answer":"analogy"},{"question_id":31,"question":"_____ something The job involves collecting and analysing data.","hint":"to examine the nature or structure of something, especially by separating it into its parts, in order to understand or explain it","correct_answer":"analyse"},{"question_id":32,"question":"an _____ donor","hint":"with a name that is not known or that is not made public","correct_answer":"anonymous"},{"question_id":33,"question":"_____ something We don''''t anticipate any major problems.","hint":"to expect something","correct_answer":"anticipate"},{"question_id":34,"question":"a piece of laboratory _____","hint":"the tools or other pieces of equipment that are needed for a particular activity or task","correct_answer":"apparatus"},{"question_id":35,"question":"_____ for something to launch a TV appeal for donations to the charity","hint":"a deeply felt request for money, help or information that is needed immediately, especially one made by a charity or by the police","correct_answer":"appeal"},{"question_id":36,"question":"Spending the holidays in Britain wasn''''t a prospect that I found particularly _____.","hint":"attractive or interesting","correct_answer":"appealing"},{"question_id":37,"question":"He suffered from headaches and loss of _____.","hint":"physical desire for food","correct_answer":"appetite"},{"question_id":38,"question":"Over the years he came to _____ the beauty and tranquillity of the river.","hint":"to recognize the good qualities of somebody/something","correct_answer":"appreciate"},{"question_id":39,"question":"an _____ response/measure/method","hint":"suitable, acceptable or correct for the particular circumstances","correct_answer":"appropriate"},{"question_id":40,"question":"The choice of players for the team seemed completely _____.","hint":"not seeming to be based on a reason, system or plan and sometimes seeming unfair","correct_answer":"arbitrary"},{"question_id":41,"question":"She struggled to _____ her thoughts.","hint":"to express or explain your thoughts or feelings clearly in words","correct_answer":"articulate"},{"question_id":42,"question":"an _____ limb/flower/sweetener/fertilizer","hint":"made or produced to copy something natural; not real","correct_answer":"artificial"},{"question_id":43,"question":"_____ of something The book aims to cover all aspects of city life.","hint":"a particular part or feature of a situation, an idea, a problem, etc.; a way in which it may be considered","correct_answer":"aspect"},{"question_id":44,"question":"_____ that… She continued to assert that she was innocent.","hint":"to state clearly and definitely that something is true","correct_answer":"assert"},{"question_id":45,"question":"_____ somebody/something Accurately assessing environmental impacts is very complex.","hint":"to make a judgement about the nature or quality of somebody/something","correct_answer":"assess"},{"question_id":46,"question":"In his job, patience is an invaluable _____.","hint":"a person or thing that is valuable or useful to somebody/something","correct_answer":"asset"},{"question_id":47,"question":"Students are required to complete all homework _____.","hint":"a task or piece of work that somebody is given to do, usually as part of their job or studies","correct_answer":"assignment"},{"question_id":48,"question":"Anyone willing to _____ can contact this number.","hint":"to help somebody to do something","correct_answer":"assist"},{"question_id":49,"question":"_____ somebody/something with somebody/something I always associate the smell of baking with my childhood.","hint":"to make a connection between people or things in your mind","correct_answer":"associate"},{"question_id":50,"question":"to seek/apply for/be granted _____","hint":"protection that a government gives to people who have left their own country, usually because they were in danger for political reasons","correct_answer":"asylum"},{"question_id":51,"question":"Wind power doesn''''t release carbon dioxide into the _____.","hint":"the mixture of gases that surrounds the earth","correct_answer":"atmosphere"},{"question_id":52,"question":"_____ towards somebody/something These societies have to change their attitudes towards women.","hint":"the way that you think and feel about somebody/something; the way that you behave towards somebody/something that shows how you think and feel","correct_answer":"attitude"},{"question_id":53,"question":"Patience is one of the most important _____ in a teacher.","hint":"a quality or feature of somebody/something","correct_answer":"attribute"},{"question_id":54,"question":"I don''''t know if the painting is _____.","hint":"known to be real and what somebody claims it is and not a copy","correct_answer":"authentic"},{"question_id":55,"question":"_____ doors","hint":"having controls that work without needing a person to operate them","correct_answer":"automatic"},{"question_id":56,"question":"a campaign in Wales for greater _____","hint":"the freedom for a country, a region or an organization to govern itself independently","correct_answer":"autonomy"},{"question_id":57,"question":"He was _____ in the deception by his wife.","hint":"xúi giục","correct_answer":"abet"},{"question_id":58,"question":"I _____ all forms of racism.","hint":"ghê tởm; ghét cay ghét đắng","correct_answer":"abhor"},{"question_id":59,"question":"_____ poverty/misery/failure","hint":"khốn khổ và hết hy vọng","correct_answer":"abject"},{"question_id":60,"question":"She has been asked to _____ the novel for radio.","hint":"rút ngắn lại, cắt bớt (sách, vở kịch,...)","correct_answer":"abridge"},{"question_id":61,"question":"The rule has been _____ by mutual consent.","hint":"bãi bỏ (luật lệ, thỏa thuận,...)","correct_answer":"abrogate"},{"question_id":62,"question":"an _____ change/halt/departure","hint":"bất ngờ, đột ngột (một cách khó chịu)","correct_answer":"abrupt"},{"question_id":63,"question":"He was a hard-working man with _____ habits.","hint":"tiết chế, có điều độ","correct_answer":"abstemious"},{"question_id":64,"question":"He _____ to demands for his resignation.","hint":"đồng ý, tán thành một ý kiến, đề nghị,...","correct_answer":"accede"},{"question_id":65,"question":"Her short hair _____ her huge eyes.","hint":"tô điểm, làm nổi bật","correct_answer":"accentuate"},{"question_id":66,"question":"a highly/widely _____ performance","hint":"ca ngợi, tán dương","correct_answer":"acclaim"},{"question_id":67,"question":"There is no higher _____ at this school than an honorary degree.","hint":"sự vinh danh/phần thưởng cho thành tựu mà mọi người ngưỡng mộ","correct_answer":"accolade"},{"question_id":68,"question":"The two sides signed a peace _____ last July.","hint":"hiệp định, hiệp ước","correct_answer":"accord"},{"question_id":69,"question":"His parents went through an _____ divorce.","hint":"chua cay, gay gắt","correct_answer":"acrimonious"},{"question_id":70,"question":"business/commercial/financial _____","hint":"sự nhạy bén","correct_answer":"acumen"},{"question_id":71,"question":"She was _____ for chewing gum in class.","hint":"khiển trách, la rầy","correct_answer":"admonish"},{"question_id":72,"question":"the _____ of new technology","hint":"sự ra đời, sự xuất hiện","correct_answer":"advent"},{"question_id":73,"question":"his old political _____","hint":"đối thủ","correct_answer":"adversary"},{"question_id":74,"question":"courage in the face of _____","hint":"nghịch cảnh","correct_answer":"adversity"},{"question_id":75,"question":"He struck me as an _____ sort of a man.","hint":"hoà nhã, dễ gần","correct_answer":"affable"},{"question_id":76,"question":"_____ Western countries","hint":"giàu có","correct_answer":"affluent"},{"question_id":77,"question":"The _____ person was seen acting suspiciously.","hint":"đã kể trước đây, đã nói ở trên","correct_answer":"aforementioned"},{"question_id":78,"question":"Pollution can _____ asthma.","hint":"làm trầm trọng thêm, làm nặng thêm","correct_answer":"aggravate"},{"question_id":79,"question":"The word _____ means \\\\"tranh luận, vận động (cho một điều gì, đặc biệt là để thay đổi một điều luật hoặc một điều gì đó trong xã hội)\\\\".","hint":"tranh luận, vận động (cho một điều gì, đặc biệt là để thay đổi một điều luật hoặc một điều gì đó trong xã hội)","correct_answer":"agitate"},{"question_id":80,"question":"They accepted the offer with _____.","hint":"sự sốt sắng","correct_answer":"alacrity"}]'),  -- exercise_data (JSON) - dùng JSON_QUOTE để đảm bảo JSON hợp lệ
    120,  -- exercise_duration (ước tính: 1.5 phút/câu)
